#!/usr/bin/env node
// Captures the price-gate fixture (specs/pricing-components.md §3 rules 68 and 71) from a COPY of a real database.
//
//   node scripts/price-gate/buildFixture.mjs <copy.db> --out server/src/tests/fixtures/price-gate/
//
// PASS A COPY, NEVER THE ORIGINAL: the application's own boot migrates the file it opens (and the lazy repairs
// of a read may write), so a path under `shadows/` is refused unless `--i-am-a-copy` says you made it one. The
// fixture is captured ONCE, on the code of the `price-gate-baseline` tag, and is never regenerated by the code of
// PR A, B or C (that would bless their changes).
//
// What it does: freezes the clock at CAPTURED_AT, boots the application on the copy, copies the allow-listed
// columns (`anonymise.js`), computes the figures of every stay and devis with the CURRENT code
// (`recompute.js`) and replays every stored intake on its stay, then writes:
//   inputs.json    { meta, tables, synthetic }   the anonymised rows the engine reads; `synthetic` = { cases, tables }
//   expected.json  { meta, stays, synthetic }    the figures per reservation id; `synthetic` = { cases, stays }
//   intakes.json   { meta, tables, expected } the anonymised intakes and what their replay produced
// Prints ids and counts only — never a name.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createRequire } from 'node:module';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');

// The day the prices are read on: every "today" of the engine (tourist-tax freeze, due dates, locked stays).
const CAPTURED_AT = '2026-11-11T12:00:00+01:00';

const args = process.argv.slice(2);
const flag = (name) => (args.includes(name) ? args[args.indexOf(name) + 1] : null);
const dbPath = args[0] && !args[0].startsWith('--') ? path.resolve(args[0]) : null;
const outDir = flag('--out');
if (!dbPath || !outDir || !fs.existsSync(dbPath)) {
  console.error('usage: buildFixture.mjs <copy.db> --out <dir> [--i-am-a-copy] [--no-verify]   (pass a COPY of the database)');
  process.exit(2);
}
if (dbPath.split(path.sep).includes('shadows') && !args.includes('--i-am-a-copy')) {
  console.error('refused: that path is under shadows/ — copy the snapshot to a temporary folder and pass the copy (or --i-am-a-copy)');
  process.exit(2);
}

process.env.DB_PATH = dbPath;
process.env.TZ = 'Europe/Paris';
const { freezeClock } = require(path.join(root, 'server/src/tests/vatRegimeGoldenFixture.js'));
freezeClock(new Date(CAPTURED_AT));

const print = console.log;
console.log = () => {};
const { mock } = require('node:test');
const db = require(path.join(root, 'server/src/database.js'));
const { anonymise, ALLOW_LIST, INTAKE_TABLES } = require('./anonymise.js');
const { recomputeStays, replayIntakes, replayGdfFixtures } = require('./recompute.js');

const present = new Set(db.prepare("SELECT name FROM sqlite_master WHERE type = 'table'").all().map((r) => r.name));
const source = {};
for (const table of Object.keys(ALLOW_LIST)) {
  if (present.has(table)) source[table] = db.prepare(`SELECT * FROM ${table} ORDER BY rowid`).all();
}
const copied = anonymise(source);
const inputsTables = Object.fromEntries(Object.entries(copied).filter(([t]) => !INTAKE_TABLES.includes(t)).sort(([a], [b]) => a.localeCompare(b)));
const intakesTables = Object.fromEntries(INTAKE_TABLES.map((t) => [t, copied[t] || []]));

const stays = recomputeStays(db);

mock.timers.enable({ apis: ['Date'], now: new Date(CAPTURED_AT).getTime() });
const pinClock = (instant) => { mock.timers.setTime(new Date(instant).getTime()); return () => mock.timers.setTime(new Date(CAPTURED_AT).getTime()); };
const intakesExpected = [...replayIntakes(db, { tables: intakesTables }, pinClock), ...replayGdfFixtures(db, pinClock)];
mock.timers.reset();
console.log = print;

// The synthetic refund stays (rule 72) are played on an empty in-memory database in a process of their own.
const syntheticFile = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'price-gate-synthetic-')), 'synthetic.json');
const played = spawnSync('node', [path.join(root, 'scripts/price-gate/buildSynthetic.js'), CAPTURED_AT, syntheticFile], {
  encoding: 'utf8', env: { ...process.env, DB_PATH: ':memory:' },
});
if (played.status !== 0) {
  console.log = print;
  console.error(`synthetic refund stays failed:\n${played.stdout}\n${played.stderr}`);
  process.exit(1);
}
const synthetic = JSON.parse(fs.readFileSync(syntheticFile, 'utf8'));
fs.rmSync(path.dirname(syntheticFile), { recursive: true, force: true });

const meta = { capturedAt: CAPTURED_AT, note: 'captured once on the price-gate-baseline code; never regenerated by PR A, B or C' };
const write = (name, value) => fs.writeFileSync(path.join(outDir, name), `${JSON.stringify(value, null, 1)}\n`);
fs.mkdirSync(outDir, { recursive: true });
write('inputs.json', { meta, tables: inputsTables, synthetic: { cases: synthetic.cases, tables: synthetic.tables } });
write('expected.json', { meta, stays, synthetic: { cases: synthetic.cases, stays: synthetic.stays } });
write('intakes.json', { meta, tables: intakesTables, expected: intakesExpected });

const all = Object.values(stays);
const count = (pick) => all.filter(pick).length;
print(`captured at ${CAPTURED_AT}`);
print(`stays: ${all.length} (reservations ${count((s) => s.kind === 'reservation')}, cancelled ${count((s) => s.kind === 'cancelled')}, devis ${count((s) => s.kind === 'devis')}, platform sales ${count((s) => s['platform.sale'] === true)})`);
print(`synthetic refund stays: ${Object.entries(synthetic.cases).map(([name, id]) => `${name}=${id}`).join(', ')}`);
print(`figures: production ${all.reduce((n, st) => n + Object.keys(st).length, 0)}, synthetic ${Object.values(synthetic.stays).reduce((n, st) => n + Object.keys(st).length, 0)}`);
print(`stays with an engine error: ${Object.entries(stays).filter(([, s]) => s['quote.error']).map(([id]) => id).join(', ') || 'none'}`);
print(`intakes: ${Object.entries(intakesTables).map(([t, rows]) => `${t} ${rows.length}`).join(', ')}; replayed ${intakesExpected.length}: ${intakesExpected.map((r) => `${r.intake}->${r.outcome}`).join(', ') || 'none'}`);
print(`tables in inputs.json: ${Object.entries(inputsTables).map(([t, rows]) => `${t} ${rows.length}`).join(', ')}`);

if (!args.includes('--no-verify')) {
  const env = { ...process.env, PRICE_GATE_FIXTURE_DIR: path.resolve(outDir) };
  delete env.DB_PATH;
  const verify = spawnSync('node', ['--test', '--require', './src/tests/setup/isolateDefaultDb.js', 'src/tests/price-gate.unit.test.js', 'src/tests/price-gate-synthetic.unit.test.js', 'src/tests/platform-intake-replay.unit.test.js'], {
    cwd: path.join(root, 'server'), encoding: 'utf8', env,
  });
  const summary = `${verify.stdout}\n${verify.stderr}`.split('\n').filter((l) => /^# (pass|fail|skipped)/.test(l)).join(' | ');
  print(`self-check (the gate on a fresh database loaded from the fixture): ${verify.status === 0 ? 'GREEN' : 'RED'} ${summary}`);
  process.exit(verify.status === 0 ? 0 : 1);
}
